<link rel="stylesheet" href="/css/landing.min.css?v=2"/>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800&amp;family=Geist:wght@400&amp;family=Material+Symbols+Outlined:wght,FILL@100..700,0..1&amp;display=swap" rel="stylesheet"/>
<link href="https://fonts.googleapis.com/css2?family=Material+Symbols+Outlined:wght,FILL@100..700,0..1&amp;display=swap" rel="stylesheet"/>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@100..900&amp;display=swap" rel="stylesheet"/>
<link rel="stylesheet" href="/css/global-network.css?v=3"/>
<style>
        .material-symbols-outlined {
            font-variation-settings: 'FILL' 0, 'wght' 400, 'GRAD' 0, 'opsz' 24;
        }
        /* Why Choose card icons: filled + larger for crisp rendering */
        .why-icon-wrap .material-symbols-outlined {
            font-variation-settings: 'FILL' 1, 'wght' 300, 'GRAD' 0, 'opsz' 40;
            font-size: 2.25rem !important;
        }
        .glass-card {
            background: rgba(255, 255, 255, 0.8);
            backdrop-filter: blur(12px);
            border: 1px solid #E2E8F0;
        }
        .blue-glow {
            filter: drop-shadow(0 0 15px rgba(0, 102, 255, 0.3));
        }
        /* Streaming icon hover animations */
        .stream-icon {
            display: flex; align-items: center; justify-content: center;
            color: #424656;
            transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
            position: relative;
        }
        .stream-icon::after {
            content: '';
            position: absolute;
            bottom: -2px; left: 50%;
            width: 0; height: 2px;
            background: currentColor;
            border-radius: 1px;
            transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
            transform: translateX(-50%);
        }
        .stream-icon svg { transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1); }
        .stream-icon:hover { transform: scale(1.22) translateY(-6px); }
        .stream-icon:hover::after { width: 70%; }
        .stream-icon:hover svg { filter: drop-shadow(0 4px 24px rgba(0,102,255,0.5)); }
        .stream-icon.whatsapp:hover svg { color: #25D366; }
        .stream-icon.x:hover svg { color: #1DA1F2; }
        .stream-icon.instagram:hover svg { color: #E4405F; }
        .stream-icon.facebook:hover svg { color: #1877F2; }
        .stream-icon.netflix:hover svg { color: #E50914; }
        .stream-icon.twitch:hover svg { color: #9146FF; }
        .stream-icon.youtube:hover svg { color: #FF0000; }
        .stream-icon.tiktok:hover svg { color: #000000; }
        /* Sub card hover animations */
        .sub-card {
            display: flex; flex-direction: column; align-items: center; justify-content: center;
            gap: 0.5rem;
            transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
            position: relative;
            overflow: hidden;
        }
        .sub-card::before {
            content: '';
            position: absolute;
            top: 0; left: -100%;
            width: 100%; height: 100%;
            background: linear-gradient(90deg, transparent, rgba(0,102,255,0.06), transparent);
            transition: left 0.6s ease;
        }
        .sub-card:hover::before { left: 100%; }
        .sub-card svg { transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1); }
        .sub-card:hover { transform: translateY(-8px) scale(1.06); border-color: #0066ff !important; box-shadow: 0 12px 36px rgba(0,102,255,0.25); }
        .sub-card:hover svg { transform: scale(1.2) rotate(5deg); filter: drop-shadow(0 4px 16px rgba(0,102,255,0.4)); }
    </style>
