<script>
        // === Theme Toggle ===
        (function() {
            const saved = localStorage.getItem('theme');
            if (saved !== 'light') {
                document.documentElement.classList.add('dark');
            }
        })();

        function toggleTheme() {
            const html = document.documentElement;
            const icon = document.getElementById('themeIcon');
            const isDark = html.classList.toggle('dark');
            localStorage.setItem('theme', isDark ? 'dark' : 'light');
            icon.textContent = isDark ? 'dark_mode' : 'light_mode';
            icon.style.transform = 'rotate(360deg)';
            setTimeout(() => { icon.style.transform = ''; }, 400);
        }

        // FAQ Accordion
        function toggleFaq(btn) {
            const item = btn.parentElement;
            const content = item.querySelector('.faq-content');
            const icon = btn.querySelector('.faq-icon');
            const numBadge = btn.querySelector('span:first-child');
            const isOpen = content.classList.contains('faq-open');
            // Close all other items
            document.querySelectorAll('.faq-item').forEach(other => {
                if (other !== item) {
                    other.querySelector('.faq-content').classList.remove('faq-open');
                    other.querySelector('.faq-icon').style.transform = 'rotate(0deg)';
                    other.querySelector('.faq-toggle span:first-child').style.background = 'rgba(109,159,255,0.12)';
                    other.querySelector('.faq-toggle span:first-child').style.color = '#6d9fff';
                    other.style.borderColor = '';
                    other.style.boxShadow = '';
                }
            });
            if (isOpen) {
                content.classList.remove('faq-open');
                icon.style.transform = 'rotate(0deg)';
                numBadge.style.background = 'rgba(109,159,255,0.12)';
                numBadge.style.color = '#6d9fff';
                item.style.borderColor = '';
                item.style.boxShadow = '';
            } else {
                content.classList.add('faq-open');
                icon.style.transform = 'rotate(180deg)';
                numBadge.style.background = '#6d9fff';
                numBadge.style.color = '#0a1a3a';
                item.style.borderColor = 'rgba(109,159,255,0.35)';
                item.style.boxShadow = '0 4px 20px rgba(109,159,255,0.1), 0 0 0 1px rgba(109,159,255,0.15)';
            }
        }

        // Language selector
        function toggleLangMenu() {
            const menu = document.getElementById('langMenu');
            menu.classList.toggle('hidden');
        }
        function switchLang(code) {
            document.getElementById('langMenu').classList.add('hidden');
            localStorage.setItem('lang', code);
            applyI18N(code);
        }

        // ── I18N Engine ──
        const I18N_DEFAULT_LANG = 'zh-CN';
        let I18N_CURRENT_LANG = I18N_DEFAULT_LANG;

        function t(section, key) {
            const group = window.I18N[section];
            if (!group || !group[key]) return '';
            return group[key][I18N_CURRENT_LANG] || group[key][I18N_DEFAULT_LANG] || '';
        }

        function jt(key) {
            // I18N.js 结构是 {key: {lang: value}}（按 key 分组），不是 {lang: {key: value}}（按 lang 分组）
            // v15.6 修复：原 lookup 假设错了，所有 jt() 调用都会抛 TypeError
            const group = window.I18N.js;
            if (!group) return '';
            const entry = group[key];
            if (!entry) return '';
            return entry[I18N_CURRENT_LANG] || entry[I18N_DEFAULT_LANG] || '';
        }

        function applyI18N(lang) {
            I18N_CURRENT_LANG = lang;
            document.documentElement.lang = lang;

            // Update text content
            document.querySelectorAll('[data-i18n]').forEach(el => {
                const path = el.getAttribute('data-i18n');
                const parts = path.split('.');
                const text = t(parts[0], parts[1]);
                if (text) el.textContent = text;
            });

            // Update placeholders
            document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
                const path = el.getAttribute('data-i18n-placeholder');
                const parts = path.split('.');
                const text = t(parts[0], parts[1]);
                if (text) el.placeholder = text;
            });

            // Update title attributes
            document.querySelectorAll('[data-i18n-title]').forEach(el => {
                const path = el.getAttribute('data-i18n-title');
                const parts = path.split('.');
                const text = t(parts[0], parts[1]);
                if (text) el.title = text;
            });

            // Update alt attributes
            document.querySelectorAll('[data-i18n-alt]').forEach(el => {
                const path = el.getAttribute('data-i18n-alt');
                const parts = path.split('.');
                const text = t(parts[0], parts[1]);
                if (text) el.alt = text;
            });

            // Update meta tags
            const metaSet = (sel, s, k) => {
                document.querySelectorAll(sel).forEach(el => {
                    const text = t(s, k);
                    if (text) el.setAttribute('content', text);
                });
            };
            metaSet('title', 'meta', 'title');
            metaSet('meta[name="description"]', 'meta', 'description');
            metaSet('meta[name="keywords"]', 'meta', 'keywords');
            metaSet('meta[property="og:title"]', 'meta', 'og_title');
            metaSet('meta[property="og:description"]', 'meta', 'og_description');
            metaSet('meta[property="og:site_name"]', 'meta', 'og_site_name');
            metaSet('meta[name="twitter:title"]', 'meta', 'twitter_title');
            metaSet('meta[name="twitter:description"]', 'meta', 'twitter_description');
            const localeMap = {'zh-CN':'zh_CN','zh-TW':'zh_TW','en':'en_US'};
            const ogLocale = document.querySelector('meta[property="og:locale"]');
            if (ogLocale && localeMap[lang]) ogLocale.setAttribute('content', localeMap[lang]);

            // Update JSON-LD
            document.querySelectorAll('[data-i18n-schema]').forEach(el => {
                const schemaKey = el.getAttribute('data-i18n-schema');
                const translated = window.I18N_JSONLD[schemaKey] && window.I18N_JSONLD[schemaKey][lang];
                if (translated) el.textContent = translated;
            });

            // Update JS string literals
            CYCLE_LABELS = {
                monthly: t('js','cycle_monthly'), quarterly: t('js','cycle_quarterly'),
                half_yearly: t('js','cycle_half_yearly'), yearly: t('js','cycle_yearly')
            };
            CYCLE_SAVE = {
                quarterly: t('js','save_quarterly'), half_yearly: t('js','save_half_yearly'),
                yearly: t('js','save_yearly')
            };

            // Update lang selector label
            const langLabel = document.getElementById('langLabel');
            if (langLabel) {
                const names = {'zh-CN':'简体中文','zh-TW':'繁體中文','en':'English'};
                langLabel.textContent = names[lang] || lang;
            }
        }
        // Close lang menu on outside click
        document.addEventListener('click', function(e) {
            const sel = document.getElementById('langSelector');
            if (sel && !sel.contains(e.target)) {
                document.getElementById('langMenu').classList.add('hidden');
            }
        });

        // Sync icon on page load + I18N init
        document.addEventListener('DOMContentLoaded', function() {
            const icon = document.getElementById('themeIcon');
            if (icon) {
                icon.textContent = document.documentElement.classList.contains('dark') ? 'dark_mode' : 'light_mode';
            }
            // Apply saved language
            const savedLang = localStorage.getItem('lang') || I18N_DEFAULT_LANG;
            applyI18N(savedLang);
        });
    </script>
<script>
        // Smooth scroll for anchors
        document.querySelectorAll('a[href^="#"]').forEach(anchor => {
            anchor.addEventListener('click', function (e) {
                e.preventDefault();
                const target = document.querySelector(this.getAttribute('href'));
                if (target) {
                    window.scrollTo({
                        top: target.offsetTop - 80,
                        behavior: 'smooth'
                    });
                }
            });
        });

        // Simple visibility observer for fade-in effect
        const observerOptions = {
            threshold: 0.1
        };

        const observer = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    entry.target.classList.add('opacity-100');
                    entry.target.classList.remove('opacity-0', 'translate-y-4');
                }
            });
        }, observerOptions);

        document.querySelectorAll('section').forEach(section => {
            section.classList.add('transition-all', 'duration-700', 'opacity-0', 'translate-y-4');
            observer.observe(section);
        });
    </script>
