const PLAN_DATA = {
  'VIP 1': { monthly: '28.00', quarterly: '79.80', half_yearly: '151.20', yearly: '285.60', plan_id: 1 },
  'VIP 2': { monthly: '38.00', quarterly: '108.30', half_yearly: '205.20', yearly: '387.60', plan_id: 2 },
  'VIP 3': { monthly: '58.00', quarterly: '165.30', half_yearly: '313.20', yearly: '591.60', plan_id: 3 }
};

/* ===== 动态数据：价格/试用时间/支付状态 ===== */
let siteConfig = { try_out_hour: 0, has_payment_methods: 1 };
let plansApiData = [];

async function initLandingData() {
  try {
    const [configRes, planRes] = await Promise.all([
      fetch('/api/v1/guest/comm/config').then(r => r.json()),
      fetch('/api/v1/guest/plan/fetch').then(r => r.json())
    ]);
    if (configRes?.data) siteConfig = configRes.data;
    if (planRes?.data) plansApiData = planRes.data;
    applyDynamicData();
  } catch(e) { console.warn('Failed to load site data', e); }
}

function normalizePlanName(name) {
  return (name || '').replace(/\s+/g, '').toUpperCase();  // "VIP 1" → "VIP1", "vip1" → "VIP1"
}

function applyDynamicData() {
  // 1. 试用时间 — 更新 I18N 字典 + 直接设置文本
  if (siteConfig.try_out_hour > 0) {
    var h = siteConfig.try_out_hour;
    // 更新 I18N 字典（3 种语言），防止语言切换时被覆盖
    if (window.I18N && window.I18N.js) {
      var subtexts = {
        'zh-CN': '所有订阅均包含 ' + h + '小时免费试用体验',
        'zh-TW': '所有訂閱均包含 ' + h + '小時免費試用體驗',
        'en': 'All plans include a ' + h + '-hour free trial'
      };
      ['zh-CN','zh-TW','en'].forEach(function(lang) {
        if (window.I18N.js[lang] && window.I18N.js[lang].plans) {
          window.I18N.js[lang].plans.subtext = subtexts[lang];
        }
      });
      // hero trial note（可能不在字典中，加进去）
      var trialNotes = {
        'zh-CN': '新注册用户免费体验 ' + h + ' 小时',
        'zh-TW': '新註冊用戶免費體驗 ' + h + ' 小時',
        'en': 'New users get ' + h + ' hours free trial'
      };
      ['zh-CN','zh-TW','en'].forEach(function(lang) {
        if (window.I18N.js[lang] && window.I18N.js[lang].hero) {
          window.I18N.js[lang].hero.trial_note = trialNotes[lang];
        }
      });
    }
    // 直接更新 DOM
    var subtextEl = document.querySelector('[data-i18n="plans.subtext"]');
    if (subtextEl) subtextEl.textContent = '所有订阅均包含 ' + h + '小时免费试用体验';
    var heroTrialEl = document.querySelector('[data-i18n="hero.trial_note"]');
    if (heroTrialEl) heroTrialEl.textContent = '新注册用户免费体验 ' + h + ' 小时';
  } else {
    if (window.I18N && window.I18N.js) {
      ['zh-CN','zh-TW','en'].forEach(function(lang) {
        if (window.I18N.js[lang] && window.I18N.js[lang].plans)
          window.I18N.js[lang].plans.subtext = { 'zh-CN': lang==='zh-CN' ? '立即注册，开启极速体验' : (lang==='zh-TW' ? '立即註冊，開啟極速體驗' : 'Sign up to get started') };
        if (window.I18N.js[lang] && window.I18N.js[lang].plans) {
          var txts = {'zh-CN':'立即注册，开启极速体验','zh-TW':'立即註冊，開啟極速體驗','en':'Sign up to get started'};
          window.I18N.js[lang].plans.subtext = txts[lang];
        }
      });
    }
    var subtextEl = document.querySelector('[data-i18n="plans.subtext"]');
    if (subtextEl) subtextEl.textContent = '立即注册，开启极速体验';
    var heroTrialEl = document.querySelector('[data-i18n="hero.trial_note"]');
    if (heroTrialEl) heroTrialEl.textContent = '立即注册，开启极速体验';
  }

  // 2. 价格（API 返回 price × 100，需除回来）
  if (plansApiData.length > 0) {
    // 建立 API name → plan 的映射（用标准化 key）
    var apiPlanMap = {};
    plansApiData.forEach(function(plan) {
      apiPlanMap[normalizePlanName(plan.name)] = plan;
    });

    // 更新 PLAN_DATA
    Object.keys(PLAN_DATA).forEach(function(key) {
      var nk = normalizePlanName(key);
      var plan = apiPlanMap[nk];
      if (!plan) return;
      if (plan.month_price != null) PLAN_DATA[key].monthly = (plan.month_price / 100).toFixed(2);
      if (plan.quarter_price != null) PLAN_DATA[key].quarterly = (plan.quarter_price / 100).toFixed(2);
      if (plan.half_year_price != null) PLAN_DATA[key].half_yearly = (plan.half_year_price / 100).toFixed(2);
      if (plan.year_price != null) PLAN_DATA[key].yearly = (plan.year_price / 100).toFixed(2);
      PLAN_DATA[key].plan_id = plan.id;
    });

    // 更新卡片上的月价
    document.querySelectorAll('.st-plan-card').forEach(function(card) {
      var h3 = card.querySelector('h3');
      if (!h3) return;
      var cardMatch = h3.textContent.trim().match(/VIP\s*\d+/);
      if (!cardMatch) return;
      var cardKey = cardMatch[0]; // "VIP 1"
      var nk = normalizePlanName(cardKey); // "VIP1"
      if (PLAN_DATA[cardKey]) {
        var pv = card.querySelector('.st-plan-price-val');
        if (pv) pv.textContent = '¥' + PLAN_DATA[cardKey].monthly;
      }
    });
  }

  // 3. 支付方式不可用 → 禁用订阅按钮
  if (!siteConfig.has_payment_methods) {
    document.querySelectorAll('[onclick^="openSubscribeModal"]').forEach(function(btn) {
      btn.disabled = true;
      btn.textContent = '暂时无法订阅';
      btn.style.opacity = '0.5';
      btn.style.cursor = 'not-allowed';
    });
  }
}

document.addEventListener('DOMContentLoaded', initLandingData);
let CYCLE_LABELS = {
  monthly: '月付',
  quarterly: '季付',
  half_yearly: '半年付',
  yearly: '年付'
};
let CYCLE_SAVE = {
  quarterly: '省5%',
  half_yearly: '省10%',
  yearly: '省15%'
};

function openSubscribeModal(plan) {
  // 已登录用户直接跳转到套餐购买页（自动选中本套餐 + 触发 checkout）
  var _t = localStorage.getItem('fe_auth_token') || localStorage.getItem('auth_token');
  if (_t) {
    var planInfo = PLAN_DATA[plan] || {};
    var url = '/dashboard/plans?checkout_plan=' + (planInfo.plan_id || '') + '&checkout_cycle=monthly' + (function(){var q=_vp92InviteQ();return q?'&'+q.substring(1):'';})();
    window.location.href = url;
    return;
  }
  selectedPlan = plan;
  selectedCycle = 'monthly';
  document.getElementById('subModalPlanName').textContent = plan + ' ' + t('modal','plan_suffix');
  // Render billing cycles
  const container = document.getElementById('subBillingCycles');
  const prices = PLAN_DATA[plan] || {};
  container.innerHTML = ['monthly','quarterly','half_yearly','yearly'].map(c => {
    const active = c === 'monthly' ? ' sub-cycle-active' : '';
    const save = CYCLE_SAVE[c] ? `<div class="sub-cycle-save">${CYCLE_SAVE[c]}</div>` : '';
    return `<div class="sub-cycle${active}" onclick="selectCycle(this,'${c}')">
      <div class="sub-cycle-label">${CYCLE_LABELS[c]}</div>
      <div class="sub-cycle-price">¥${prices[c] || '-'}</div>
      ${save}
    </div>`;
  }).join('');
  document.getElementById('subscribeModal').style.display = 'flex';
  document.body.style.overflow = 'hidden';
}
function closeSubscribeModal() {
  document.getElementById('subscribeModal').style.display = 'none';
  document.body.style.overflow = '';
  document.getElementById('subError').style.display = 'none';
}
function selectPay(el) {
  document.querySelectorAll('.sub-pay-option').forEach(o => o.classList.remove('sub-pay-active'));
  el.classList.add('sub-pay-active');
}
function selectCycle(el, cycle) {
  selectedCycle = cycle;
  document.querySelectorAll('.sub-cycle').forEach(o => o.classList.remove('sub-cycle-active'));
  el.classList.add('sub-cycle-active');
}
function handleSendCode() {
  const email = document.getElementById('subEmail').value.trim();
  if (!email || !email.includes('@')) {
    showSubError(jt('err_invalid_email')); return;
  }
  const btn = document.getElementById('subSendCode');
  codeCooldown = 60;
  btn.disabled = true;
  codeTimer = setInterval(() => {
    codeCooldown--;
    btn.textContent = codeCooldown + 's';
    if (codeCooldown <= 0) { clearInterval(codeTimer); btn.textContent = jt('btn_send_code'); btn.disabled = false; }
  }, 1000);

  fetch('/api/v1/passport/comm/sendEmailVerify', {
    method: 'POST', headers: {'Content-Type':'application/json','Accept':'application/json'},
    body: JSON.stringify({email: email})
  }).then(r => r.json()).then(data => {
    if (data.status === 'success') return;
    showSubError(data.message || jt('err_code_failed'));
    clearInterval(codeTimer); btn.textContent = jt('btn_send_code'); btn.disabled = false;
  }).catch(() => {
    showSubError(jt('err_network'));
    clearInterval(codeTimer); btn.textContent = jt('btn_send_code'); btn.disabled = false;
  });
}
function handleSubscribe() {
  try {
  const email = document.getElementById('subEmail').value.trim();
  const password = document.getElementById('subPassword').value;
  const emailCode = document.getElementById('subCode').value.trim();
  if (!email || !password || !emailCode) { showSubError(jt('err_incomplete')); return; }
  if (password.length < 8) { showSubError(jt('err_password_short')); return; }

  const btn = document.getElementById('subSubmitBtn');
  btn.disabled = true; btn.textContent = jt('btn_registering');

  fetch('/api/v1/passport/auth/register', {
    method: 'POST', headers: {'Content-Type':'application/json','Accept':'application/json'},
    body: JSON.stringify({email: email, password: password, password_confirm: password, email_code: emailCode, invite_code: _vp92GetInvite()})
  }).then(r => r.json()).then(data => {
    if (data.status === 'success') {
      // Login first, then redirect to checkout
      fetch('/api/v1/passport/auth/login', {
        method: 'POST', headers: {'Content-Type':'application/json','Accept':'application/json'},
        body: JSON.stringify({email: email, password: password})
      }).then(r => r.json()).then(loginData => {
        if (loginData.data && loginData.data.auth_data) {
          // Save auth token
          const auth = loginData.data.auth_data;
          localStorage.setItem('fe_auth_token', auth.token);
        }
        // Redirect to plans page with auto-checkout params (Dashboard SPA reads them)
        const planInfo = PLAN_DATA[selectedPlan] || {};
        const checkoutUrl = '/dashboard/plans?checkout_plan=' + (planInfo.plan_id || '') + '&checkout_cycle=' + selectedCycle + (function(){var q=_vp92InviteQ();return q?'&'+q.substring(1):'';})();
        window.location.href = checkoutUrl;
      }).catch(() => {
        const planInfo = PLAN_DATA[selectedPlan] || {};
        const checkoutUrl = '/dashboard/plans?checkout_plan=' + (planInfo.plan_id || '') + '&checkout_cycle=' + selectedCycle + (function(){var q=_vp92InviteQ();return q?'&'+q.substring(1):'';})();
        window.location.href = checkoutUrl;
      });
    } else {
      showSubError(data.message || jt('err_register_failed'));
      btn.disabled = false; btn.textContent = jt('btn_submit');
    }
  }).catch(() => {
    showSubError(jt('err_network'));
    btn.disabled = false; btn.textContent = jt('btn_submit');
  });
  } catch (e) {
    // v15.6 修复：同步代码抛错时显示错误并重置按钮状态
    console.error('handleSubscribe sync error:', e);
    showSubError(jt('err_network'));
    const btn = document.getElementById('subSubmitBtn');
    if (btn) { btn.disabled = false; btn.textContent = jt('btn_submit'); }
  }
}
function showSubError(msg) {
  const el = document.getElementById('subError');
  el.textContent = msg; el.style.display = 'block';
}

// Close on ESC
document.addEventListener('keydown', e => { if (e.key === 'Escape') closeSubscribeModal(); });
</script>

