<!-- Cookie Banner -->
<div id="cookieBanner">
  <div class="cb-inner">
    <div class="cb-text" data-i18n="cookie.banner_text">我们使用 Cookie 来提升您的浏览体验、分析网站流量。点击"全部接受"即表示您同意我们使用 Cookie。</div>
    <div class="cb-btns">
