      <div class="cm-cat-header">
        <div>
          <div class="cm-cat-name" data-i18n="cookie.analytics">分析 Cookie</div>
          <div class="cm-cat-desc" data-i18n="cookie.analytics_desc">用于 Google Analytics 等数据统计，帮助我们改善网站。</div>
        </div>
