      <div class="cm-cat-header">
        <div>
          <div class="cm-cat-name" data-i18n="cookie.marketing">营销/广告 Cookie</div>
          <div class="cm-cat-desc" data-i18n="cookie.marketing_desc">用于个性化广告投放和推广。</div>
        </div>
